def mask(R, subj, tier, era=None):
    T = MATTIER[tier]; mat = PROERA[era][0] if era and tier == 'pro' else R.choice(ERA[era]['mats']) if era and (tier.startswith('homemade') or tier.startswith('store')) else R.choice(T['mats'])
    cv = R.choice(COVER)
    flaw = R.choice(T['flaws']); parts = [f"{T['label'].capitalize()} of {('an ' if subj[0].lower() in 'aeiou' else 'a ')}{subj}, made of {mat}", f"it is {cv}", f"with {R.choice(EYES)}, {R.choice(MOUTH)}, {R.choice(TEXT)} and {R.choice(HAIR)}", f"held on with {'a handle stick' if 'stick' in cv else 'a headband' if 'top of the head' in cv else R.choice(SEAM)}", f"details: {flaw}"]
    if era: parts.append(f"typical of the {era}: {PROERA[era][1] if tier == 'pro' else ERA[era]['style']}")
    return '; '.join(parts) + '.'
