def costume(R, c, tier, era):
    em = ERA[era]
    return f"A {c}, {R.choice(CTIER[tier])}. Quality: {QL[tier]}. Era feel ({era}): {PROERA[era][1] if tier == 'pro' else em['style']}, with {PROERA[era][0] if tier == 'pro' else R.choice(em['mats'])}. Mask: {mask(R, R.choice(SUBJ), tier, era).split(';')[0]}."
def build():
    G = {}
    allm = []; allc = []
    for tier, T in MATTIER.items():
        out = []
        for i in range(260):
            R = rg('hm', tier, i); out.append(mask(R, R.choice(SUBJ), tier, R.choice(DEC)))
        G[f'halloween_mask_{tier}'] = sorted(set(out)); allm += out
    G['halloween_mask'] = sorted(set(allm))
    full = [x for x in G['halloween_mask'] if re.search(r'full-head|full-face|hood-mask|mask-and-neck|movable jaw|open mouth|open jaw', x)]
    part = [x for x in G['halloween_mask'] if re.search(r'half mask|lower-face|domino|half-skull|half-face|eye-mask|on a stick|on top of the head|flip-up|face-and-horns|snout', x)]
    G['halloween_mask_full'] = full or G['halloween_mask'][:50]; G['halloween_mask_partial'] = part or G['halloween_mask'][:50]
    for d in DEC:
        G[f'halloween_mask_{d}'] = sorted({mask(rg('hme', d, i), rg('hs', d, i).choice(SUBJ), rg('ht', d, i).choice(list(MATTIER)), d) for i in range(120)})
    G['halloween_mask_subject'] = SUBJ; G['halloween_mask_cover'] = COVER; G['halloween_mask_closure'] = SEAM; G['halloween_mask_hair'] = HAIR; G['halloween_mask_eyes'] = EYES; G['halloween_mask_mouth'] = MOUTH; G['halloween_mask_texture'] = TEXT
    G['halloween_mask_material'] = sorted({m for t in MATTIER.values() for m in t['mats']} | {m for e in ERA.values() for m in e['mats']})
    for tier in MATTIER: G[f'halloween_mask_material_{tier}'] = MATTIER[tier]['mats']
    G['halloween_mask_era_style'] = [f'{d}: {ERA[d]["style"]}' for d in DEC]
    for tier in CTIER:
        out = []
        for i in range(330):
            R = rg('hc', tier, i); out.append(costume(R, R.choice(COST), tier, R.choice(DEC)))
        G[f'halloween_costume_{tier}'] = sorted(set(out)); allc += out
    G['halloween_costume'] = sorted(set(allc)); G['halloween_costume_name'] = COST
    for d in DEC: G[f'halloween_costume_{d}'] = sorted({costume(rg('hce', d, i), rg('hcc', d, i).choice(COST), rg('hct', d, i).choice(list(CTIER)), d) for i in range(150)})
    G['halloween_costume_then_and_now'] = [f"{c}: in the 1920s made from {ERA['1920s']['mats'][0]} with {ERA['1920s']['style']}; today made from {ERA['2020s']['mats'][0]} with {ERA['2020s']['style']}." for c in COST[:60]]
    G['halloween_prompt'] = ['__halloween_costume__', '__halloween_mask__', 'Wearing __halloween_mask_full__', 'Wearing __halloween_mask_partial__', '__halloween_mask_pro__', '__halloween_mask_homemade_bad__', '__halloween_mask_homemade_great__', '__halloween_mask_store_bad__', '__halloween_mask_store_great__', '__halloween_costume_pro__']
    return G
def run(final):
    G = build()
    for n, l in G.items():
        assert l and all(l), n
        open(os.path.join(final, n + '.txt'), 'w', encoding='utf8', newline='\n').write('\n'.join(l) + '\n')
    print('halloween:', len(G), 'files;', len(G['halloween_mask']), 'masks;', len(G['halloween_costume']), 'costumes'); return G
def export_aoo(out, prefix='aoo_'):
    G = build(); names_ = set(G); ref = re.compile(r'__([A-Za-z0-9_\-/]+)__'); n = 0
    for name, lines in G.items():
        keep = list(dict.fromkeys(ref.sub(lambda m: '__' + prefix + m.group(1) + '__' if m.group(1) in names_ else m.group(0), l) for l in lines))
        if name != 'halloween_prompt': random.Random(zlib.crc32(name.encode())).shuffle(keep)
        open(os.path.join(out, prefix + name + '.txt'), 'w', encoding='utf8', newline='\n').write('\n'.join(keep) + '\n'); n += 1
    return n
if __name__ == '__main__':
    a = [x for x in sys.argv[1:] if os.path.isdir(x)]; run(os.path.abspath(a[0]) if a else FINAL)
